  if (DM_LEVEL.kind === 'water') { dmRenderWater(st); return; }
  if (st.maze.flat) { dmRenderBoxes(st); return; }
  if (DM_LEVEL.kind === 'sky') { dmRenderSky(st); return; }
  if (DM_LEVEL.kind === 'keys') { dmRenderKeys(st); return; }
